"use client";

import { createSHA256 } from "hash-wasm";
import { useEffect, useLayoutEffect, useReducer, useRef, useState } from "react";
import {
  DEFAULT_LAN_PORT,
  MAX_ATTACHMENT_BYTES,
  MAX_DEVICE_NAME_LENGTH,
  previewKind,
  PROTOCOL_VERSION,
  routes,
  type ClientMessage,
  type Device,
  type Message,
  type ServerEvent,
} from "@landrop/protocol";

const LAN_PORT = Number(process.env.NEXT_PUBLIC_LANDROP_PORT ?? DEFAULT_LAN_PORT);
const HASH_SLICE_BYTES = 8 * 1024 * 1024;
const RECONNECT_MS = 2000;
const IDENTITY_KEY = "landrop.identity";

export interface Progress {
  bytesReceived: number;
  bytesPerSecond: number;
}

interface State {
  connection: "connecting" | "online" | "offline";
  self?: Device;
  token?: string;
  isHost: boolean;
  online: Device[];
  /** Current name of every device by id, so renames apply to earlier messages too. */
  names: Record<string, string>;
  messages: Message[];
  progress: Record<string, Progress>;
  notice?: string;
}

type Action = { type: "event"; event: ServerEvent } | { type: "disconnected" } | { type: "notice"; notice?: string };

const initialState: State = { connection: "connecting", isHost: false, online: [], names: {}, messages: [], progress: {} };

const withNames = (names: Record<string, string>, devices: Device[]) => ({
  ...names,
  ...Object.fromEntries(devices.map((d) => [d.id, d.name])),
});

function upsert(messages: Message[], message: Message): Message[] {
  const index = messages.findIndex((m) => m.id === message.id);
  if (index === -1) return [...messages, message];
  const next = [...messages];
  next[index] = message;
  return next;
}

function reducer(state: State, action: Action): State {
  if (action.type === "disconnected") return { ...state, connection: "offline", online: [], token: undefined };
  if (action.type === "notice") return { ...state, notice: action.notice };
  const e = action.event;
  switch (e.type) {
    case "session:welcome":
      return {
        ...state,
        connection: "online",
        self: e.self,
        token: e.token,
        isHost: e.isHost,
        online: e.online,
        names: withNames({}, [...e.directory, ...e.online]),
        messages: e.messages,
      };
    case "presence:update":
      return { ...state, online: e.online, names: withNames(state.names, e.online) };
    case "message:created":
    case "message:updated":
      return { ...state, messages: upsert(state.messages, e.message) };
    case "attachment:progress":
      return { ...state, progress: { ...state.progress, [e.messageId]: e } };
    case "message:deleted": {
      const progress = { ...state.progress };
      delete progress[e.messageId];
      return { ...state, messages: state.messages.filter((m) => m.id !== e.messageId), progress };
    }
    case "error":
      return { ...state, notice: e.message };
  }
}

export default function LanDrop() {
  const [state, dispatch] = useReducer(reducer, initialState);
  const [text, setText] = useState("");
  const [files, setFiles] = useState<File[]>([]);
  const [replyTo, setReplyTo] = useState<Message>();
  /** The message whose press-and-hold menu is open. */
  const [selected, setSelected] = useState<Message>();
  const [dragging, setDragging] = useState(false);
  const [renaming, setRenaming] = useState(false);
  /** dragenter/dragleave fire for every child element; count them so the overlay doesn't flicker. */
  const dragDepth = useRef(0);
  const [viewing, setViewing] = useState<Message>();
  const socketRef = useRef<WebSocket | null>(null);
  const tokenRef = useRef<string | undefined>(undefined);
  const identityRef = useRef<Identity | null>(null);
  /** Uploads in progress by message id, so they can be stopped if the connection drops. */
  const uploadsRef = useRef(new Map<string, { stopped: boolean; xhr?: XMLHttpRequest }>());
  const bottomRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const serverBase = () => `${location.protocol}//${location.hostname}:${LAN_PORT}`;

  async function api<T>(path: string, method: string, body?: unknown): Promise<T> {
    const res = await fetch(serverBase() + path, {
      method,
      headers: {
        authorization: `Bearer ${tokenRef.current}`,
        ...(body !== undefined && { "content-type": "application/json" }),
      },
      body: body === undefined ? undefined : JSON.stringify(body),
    });
    if (res.status === 204) return undefined as T;
    const json = await res.json().catch(() => ({}));
    if (!res.ok) throw new Error(json.message ?? `Request failed (${res.status})`);
    return json as T;
  }

  useEffect(() => {
    identityRef.current = loadIdentity();
    let disposed = false;
    let retry: ReturnType<typeof setTimeout> | undefined;

    const open = () => {
      clearTimeout(retry);
      const scheme = location.protocol === "https:" ? "wss" : "ws";
      const socket = new WebSocket(`${scheme}://${location.hostname}:${LAN_PORT}${routes.ws}`);
      socketRef.current = socket;
      socket.onopen = () => {
        const { deviceId, deviceSecret, name } = identityRef.current!;
        const hello: ClientMessage = { type: "hello", protocolVersion: PROTOCOL_VERSION, deviceId, deviceSecret, name };
        socket.send(JSON.stringify(hello));
      };
      socket.onmessage = (raw) => {
        const event = JSON.parse(raw.data) as ServerEvent;
        if (event.type === "session:welcome") tokenRef.current = event.token;
        dispatch({ type: "event", event });
      };
      socket.onclose = () => {
        if (disposed || socketRef.current !== socket) return;
        tokenRef.current = undefined;
        for (const upload of uploadsRef.current.values()) {
          upload.stopped = true;
          upload.xhr?.abort();
        }
        dispatch({ type: "disconnected" });
        retry = setTimeout(open, RECONNECT_MS);
      };
    };

    // Phones suspend background pages; reconnect the moment the user comes back.
    const onVisible = () => {
      const s = socketRef.current;
      if (document.visibilityState === "visible" && (!s || s.readyState >= WebSocket.CLOSING)) open();
    };
    document.addEventListener("visibilitychange", onVisible);
    open();
    return () => {
      disposed = true;
      clearTimeout(retry);
      document.removeEventListener("visibilitychange", onVisible);
      socketRef.current?.close();
    };
  }, []);

  // Keep the newest message in view, like a chat app.
  useLayoutEffect(() => {
    bottomRef.current?.scrollIntoView({ block: "end" });
  }, [state.messages.length]);

  function rename(name: string) {
    setRenaming(false);
    const current = identityRef.current;
    if (!current || !name || name === current.name) return;
    identityRef.current = { ...current, name };
    saveIdentity(identityRef.current);
    const update: ClientMessage = { type: "profile:update", name };
    socketRef.current?.send(JSON.stringify(update));
  }

  function chooseFiles(picked: File[]) {
    const tooBig = picked.filter((f) => f.size > MAX_ATTACHMENT_BYTES);
    setFiles((current) => [...current, ...picked.filter((f) => f.size <= MAX_ATTACHMENT_BYTES)]);
    dispatch({
      type: "notice",
      notice: tooBig.length
        ? `Files over ${formatBytes(MAX_ATTACHMENT_BYTES)} can't be sent: ${tooBig.map((f) => f.name).join(", ")}`
        : undefined,
    });
    if (fileInputRef.current) fileInputRef.current.value = "";
  }

  async function send() {
    if (state.connection !== "online") {
      return dispatch({ type: "notice", notice: "Not connected to the LANDrop host yet. Reconnecting…" });
    }
    const body = text.trim();
    const toUpload = files;
    if (!body && toUpload.length === 0) return;
    // The reply quote goes on the first message sent: the text, or else the first attachment.
    let replyToId = replyTo?.id;
    setText("");
    setFiles([]);
    setReplyTo(undefined);
    try {
      if (body) {
        await api<Message>(routes.messages, "POST", { text: body, replyToId });
        replyToId = undefined;
      }
      for (const file of toUpload) {
        const message = await api<Message>(routes.messages, "POST", {
          replyToId,
          attachment: { name: file.name, size: file.size, mimeType: file.type || "application/octet-stream" },
        });
        replyToId = undefined;
        void uploadAttachment(message.id, file);
      }
    } catch (err) {
      dispatch({ type: "notice", notice: `Couldn't send: ${(err as Error).message}` });
    }
  }

  async function uploadAttachment(messageId: string, file: File) {
    const control: { stopped: boolean; xhr?: XMLHttpRequest } = { stopped: false };
    uploadsRef.current.set(messageId, control);
    try {
      // Upload and hash in parallel: the host hashes what arrives, we hash the original.
      const [, sha256] = await Promise.all([putFile(routes.attachmentData(messageId), file, control), hashFile(file, control)]);
      await api(routes.attachmentChecksum(messageId), "POST", { sha256 });
    } catch (err) {
      if (!control.stopped) dispatch({ type: "notice", notice: `${file.name} failed to send: ${(err as Error).message}` });
    } finally {
      uploadsRef.current.delete(messageId);
    }
  }

  function putFile(path: string, file: File, control: { stopped: boolean; xhr?: XMLHttpRequest }) {
    return new Promise<void>((resolve, reject) => {
      const xhr = new XMLHttpRequest();
      control.xhr = xhr;
      xhr.open("PUT", serverBase() + path);
      xhr.setRequestHeader("authorization", `Bearer ${tokenRef.current}`);
      xhr.setRequestHeader("content-type", "application/octet-stream");
      xhr.onload = () =>
        xhr.status < 300 ? resolve() : reject(new Error(safeMessage(xhr.responseText) ?? `HTTP ${xhr.status}`));
      xhr.onerror = () => reject(new Error("Connection to the host was lost"));
      xhr.onabort = () => reject(new Error("Upload stopped"));
      // The browser streams the File from disk; it is never read into memory here.
      xhr.send(file);
    });
  }

  async function removeMessage(message: Message) {
    setSelected(undefined);
    const upload = uploadsRef.current.get(message.id);
    if (upload) {
      upload.stopped = true;
      upload.xhr?.abort();
    }
    try {
      await api(routes.message(message.id), "DELETE");
    } catch (err) {
      dispatch({ type: "notice", notice: `Couldn't remove: ${(err as Error).message}` });
    }
  }

  function showMessage(id: string) {
    const el = document.getElementById(`message-${id}`);
    if (!el) return dispatch({ type: "notice", notice: "The original message was removed." });
    el.scrollIntoView({ block: "center", behavior: "smooth" });
    el.animate([{ opacity: 0.35 }, { opacity: 1 }], { duration: 700, delay: 250 });
  }

  const others = state.online.filter((d) => d.id !== state.self?.id);
  /** A device's current name; the name stored on the message is only a fallback for devices not in the directory. */
  const nameOf = (id: string | undefined, fallback: string) => (id && state.names[id]) || fallback;

  const isFileDrag = (e: React.DragEvent) => e.dataTransfer.types.includes("Files");
  const dropHandlers = {
    onDragEnter: (e: React.DragEvent) => {
      if (!isFileDrag(e)) return;
      e.preventDefault();
      dragDepth.current += 1;
      setDragging(true);
    },
    onDragOver: (e: React.DragEvent) => {
      if (!isFileDrag(e)) return;
      e.preventDefault(); // required for the drop event to fire
      e.dataTransfer.dropEffect = "copy";
    },
    onDragLeave: (e: React.DragEvent) => {
      if (!isFileDrag(e)) return;
      dragDepth.current = Math.max(0, dragDepth.current - 1);
      if (dragDepth.current === 0) setDragging(false);
    },
    onDrop: (e: React.DragEvent) => {
      if (!isFileDrag(e)) return;
      e.preventDefault();
      dragDepth.current = 0;
      setDragging(false);
      // Browsers hand folders over as empty File entries that can't be read; leave them out.
      const items = [...e.dataTransfer.items].filter((item) => item.kind === "file");
      const folders = items.filter((item) => item.webkitGetAsEntry()?.isDirectory).length;
      const dropped = items.filter((item) => !item.webkitGetAsEntry()?.isDirectory).map((item) => item.getAsFile()!);
      chooseFiles(dropped.filter(Boolean));
      if (folders) dispatch({ type: "notice", notice: "Folders can't be sent yet. Drop the files inside them instead." });
    },
  };
  // Presence carries the latest name, including renames made in another tab of this browser.
  const selfName = state.online.find((d) => d.id === state.self?.id)?.name ?? state.self?.name;

  return (
    // App chrome, not a document: no text selection or iOS callouts anywhere except the message field.
    <div
      {...dropHandlers}
      className="relative flex h-dvh flex-col bg-background select-none [-webkit-touch-callout:none] [-webkit-user-select:none]"
    >
      <header className="sticky top-0 z-10 flex items-center gap-3 border-b border-separator bg-bar/80 px-3 pb-2 pt-[max(0.5rem,env(safe-area-inset-top))] backdrop-blur-xl">
        <span aria-hidden className="flex size-10 shrink-0 items-center justify-center rounded-full bg-ios-blue text-white">
          <GroupIcon />
        </span>
        <div className="min-w-0 flex-1">
          <h1 className="truncate text-[17px] font-semibold leading-tight">LANDrop</h1>
          {/* Like a WhatsApp group: who is here right now, or the connection state while it isn't live. */}
          <p className={`truncate text-[13px] ${state.connection === "offline" ? "text-ios-red" : "text-muted"}`}>
            {state.connection === "online"
              ? others.length
                ? [...others.map((d) => d.name), "You"].join(", ")
                : "Only you are online"
              : state.connection === "connecting"
                ? "connecting…"
                : "Can't reach the host. Retrying…"}
          </p>
        </div>
        <button
          onClick={() => setRenaming(true)}
          className="shrink-0 rounded-full"
          aria-label={`You are ${selfName ?? "joining"}. Change your name`}
          title={`${selfName ?? ""} · tap to rename`}
        >
          <Avatar name={selfName ?? "?"} />
        </button>
      </header>

      <main className="flex-1 overflow-y-auto px-3 pb-2 pt-3" aria-live="polite">
        <div className="mx-auto flex max-w-2xl flex-col">
          {state.messages.length === 0 && state.connection === "online" && (
            <p className="mt-20 text-center text-[13px] text-muted">
              No messages yet.
              <br />
              Anyone on this Wi-Fi who opens this page joins the chat.
            </p>
          )}
          {state.messages.map((m, i) => {
            const prev = state.messages[i - 1];
            const next = state.messages[i + 1];
            const newDay = !prev || new Date(prev.createdAt).toDateString() !== new Date(m.createdAt).toDateString();
            const startsRun = newDay || prev.senderId !== m.senderId || m.createdAt - prev.createdAt > TIME_GAP_MS;
            const endsRun = !next || next.senderId !== m.senderId || next.createdAt - m.createdAt > TIME_GAP_MS;
            return (
              <div key={m.id} className={startsRun ? "mt-2" : "mt-0.5"}>
                {newDay && (
                  <p className="mx-auto my-2 w-fit rounded-full bg-bubble-other px-3 py-1 text-center text-[11px] font-medium text-muted">
                    {formatDay(m.createdAt)}
                  </p>
                )}
                <Bubble
                  message={m}
                  nameOf={nameOf}
                  own={m.senderId === state.self?.id}
                  tail={endsRun}
                  progress={state.progress[m.id]}
                  downloadUrl={`${serverBase()}${routes.attachment(m.id)}?token=${state.token}`}
                  previewUrl={`${serverBase()}${routes.attachmentPreview(m.id)}?token=${state.token}`}
                  onOpenImage={() => setViewing(m)}
                  onReply={() => setReplyTo(m)}
                  onLongPress={() => {
                    // iOS may already have started selecting under the finger; clear it before the menu opens.
                    window.getSelection()?.removeAllRanges();
                    setSelected(m);
                  }}
                  onQuoteTap={showMessage}
                />
              </div>
            );
          })}
          <div ref={bottomRef} />
        </div>
      </main>

      {state.notice && (
        <div
          role="alert"
          className="mx-3 mb-2 flex items-start justify-between gap-3 rounded-2xl bg-ios-red/10 px-3 py-2 text-[13px]"
        >
          <span>{state.notice}</span>
          <button className="shrink-0 text-muted" onClick={() => dispatch({ type: "notice" })} aria-label="Dismiss">
            ✕
          </button>
        </div>
      )}

      <footer className="border-t border-separator bg-bar/80 px-2 pt-2 pb-[max(0.5rem,env(safe-area-inset-bottom))] backdrop-blur-xl">
        <div className="mx-auto flex max-w-2xl flex-col gap-2">
          {replyTo && (
            <div className="ml-11 flex items-center gap-2 rounded-lg border-l-[3px] border-ios-blue bg-bubble-other/60 px-2.5 py-1.5">
              <div className="min-w-0 flex-1 text-[13px] leading-[17px]">
                <p className="font-semibold text-ios-blue">
                  Replying to {replyTo.senderId === state.self?.id ? "yourself" : nameOf(replyTo.senderId, replyTo.senderName)}
                </p>
                <p className="truncate text-muted">{replyTo.text ?? `📄 ${replyTo.attachment?.name}`}</p>
              </div>
              <button className="shrink-0 text-muted" aria-label="Cancel reply" onClick={() => setReplyTo(undefined)}>
                ✕
              </button>
            </div>
          )}
          {files.length > 0 && (
            <ul className="flex flex-wrap gap-1.5 pl-11">
              {files.map((f, i) => (
                <li
                  key={`${f.name}-${i}`}
                  className="flex items-center gap-1.5 rounded-full bg-bubble-other px-2.5 py-1 text-[12px]"
                >
                  <span className="max-w-44 truncate">{f.name}</span>
                  <span className="text-muted">{formatBytes(f.size)}</span>
                  <button
                    aria-label={`Remove ${f.name}`}
                    className="text-muted"
                    onClick={() => setFiles(files.filter((_, j) => j !== i))}
                  >
                    ✕
                  </button>
                </li>
              ))}
            </ul>
          )}
          <div className="flex items-end gap-2">
            <label className="flex size-9 shrink-0 cursor-pointer items-center justify-center rounded-full bg-bubble-other text-muted">
              <PlusIcon />
              <span className="sr-only">Attach files (up to {formatBytes(MAX_ATTACHMENT_BYTES)} each)</span>
              <input
                ref={fileInputRef}
                type="file"
                multiple
                className="hidden"
                onChange={(e) => chooseFiles([...(e.target.files ?? [])])}
              />
            </label>
            <div className="flex min-h-9 flex-1 items-end rounded-[18px] border border-separator bg-background pl-3.5 pr-1">
              <textarea
                value={text}
                onChange={(e) => setText(e.target.value)}
                onKeyDown={(e) => {
                  // On phones Return adds a line, like Messages; on computers Enter sends.
                  if (e.key === "Enter" && !e.shiftKey && !matchMedia("(pointer: coarse)").matches) {
                    e.preventDefault();
                    void send();
                  }
                }}
                rows={1}
                placeholder="Message"
                aria-label="Message"
                className="max-h-36 min-h-[34px] flex-1 resize-none bg-transparent select-text [-webkit-user-select:text] py-[7px] text-[16px] leading-5 outline-none [field-sizing:content]"
              />
              {(text.trim() || files.length > 0) && (
                <button
                  onClick={() => void send()}
                  aria-label="Send"
                  className="my-[3px] ml-1 flex size-7 shrink-0 items-center justify-center rounded-full bg-ios-blue text-white"
                >
                  <ArrowUpIcon />
                </button>
              )}
            </div>
          </div>
        </div>
      </footer>

      {viewing?.attachment && (
        <ImageViewer
          name={viewing.attachment.name}
          url={`${serverBase()}${routes.attachmentPreview(viewing.id)}?token=${state.token}`}
          downloadUrl={`${serverBase()}${routes.attachment(viewing.id)}?token=${state.token}`}
          onClose={() => setViewing(undefined)}
        />
      )}

      {dragging && (
        <div className="pointer-events-none absolute inset-2 z-40 flex items-center justify-center rounded-3xl border-2 border-dashed border-ios-blue bg-background/85 backdrop-blur-sm">
          <div className="flex flex-col items-center gap-2 text-ios-blue">
            <PlusIcon />
            <p className="text-[17px] font-semibold">Drop to attach</p>
            <p className="text-[13px] text-muted">Up to {formatBytes(MAX_ATTACHMENT_BYTES)} per file</p>
          </div>
        </div>
      )}

      {renaming && <RenameDialog current={selfName ?? ""} onSave={rename} onCancel={() => setRenaming(false)} />}

      {selected && (
        <MessageSheet
          message={selected}
          saveUrl={`${serverBase()}${routes.attachment(selected.id)}?token=${state.token}`}
          // Senders can remove their own messages; the host can remove any (enforced again by the server).
          canRemove={selected.senderId === state.self?.id || state.isHost}
          onReply={() => {
            setReplyTo(selected);
            setSelected(undefined);
          }}
          onRemove={() => removeMessage(selected)}
          onClose={() => setSelected(undefined)}
        />
      )}
    </div>
  );
}

// ---------- Identity ----------

interface Identity {
  deviceId: string;
  deviceSecret: string;
  name: string;
}

/** A device keeps the same identity across reloads so its messages stay attributed to it. */
function loadIdentity(): Identity {
  try {
    const stored = JSON.parse(localStorage.getItem(IDENTITY_KEY) ?? "null") as Identity | null;
    if (stored?.deviceId && stored.deviceSecret && stored.name) return stored;
  } catch {
    // Storage unavailable (e.g. private browsing): fall through to a fresh identity for this visit.
  }
  const identity = { deviceId: randomHex(16), deviceSecret: randomHex(32), name: defaultDeviceName() };
  saveIdentity(identity);
  return identity;
}

function saveIdentity(identity: Identity) {
  try {
    localStorage.setItem(IDENTITY_KEY, JSON.stringify(identity));
  } catch {
    // Not persisted; the identity lasts for this visit only.
  }
}

/** crypto.getRandomValues works on plain-HTTP LAN pages, unlike crypto.randomUUID. */
function randomHex(bytes: number): string {
  return [...crypto.getRandomValues(new Uint8Array(bytes))].map((b) => b.toString(16).padStart(2, "0")).join("");
}

function defaultDeviceName(): string {
  const ua = navigator.userAgent;
  const os = /iPhone/.test(ua)
    ? "iPhone"
    : /iPad/.test(ua)
      ? "iPad"
      : /Android/.test(ua)
        ? "Android"
        : /Mac OS X/.test(ua)
          ? "Mac"
          : /Windows/.test(ua)
            ? "Windows"
            : /Linux/.test(ua)
              ? "Linux"
              : "Device";
  const browser = /Edg\//.test(ua)
    ? "Edge"
    : /Firefox\/|FxiOS/.test(ua)
      ? "Firefox"
      : /Chrome\/|CriOS/.test(ua)
        ? "Chrome"
        : /Safari\//.test(ua)
          ? "Safari"
          : "Browser";
  return `${browser} on ${os}`;
}

// ---------- Helpers ----------

async function hashFile(file: File, control: { stopped: boolean }): Promise<string> {
  const hasher = await createSHA256();
  hasher.init();
  for (let offset = 0; offset < file.size; offset += HASH_SLICE_BYTES) {
    if (control.stopped) throw new Error("Stopped");
    // One slice in memory at a time; awaiting each read keeps the UI responsive.
    hasher.update(new Uint8Array(await file.slice(offset, offset + HASH_SLICE_BYTES).arrayBuffer()));
  }
  return hasher.digest("hex");
}

function safeMessage(body: string): string | undefined {
  try {
    return JSON.parse(body).message;
  } catch {
    return undefined;
  }
}

